// Clears seven words at moby+0x00..0x18 (walking down) and a halfword at 0x1C.
void reset_shot_tracking(char *moby) {
    int *p = (int *)(moby + 0x18);
    int i;
    for (i = 6; i >= 0; i--, p--) {
        *p = 0;
    }
    *(short *)(moby + 0x1C) = 0;
}
